package android.widget;
public class AutoCompleteTextView extends EditText implements Filter.FilterListener { public interface OnDismissListener { void onDismiss(); } private ListAdapter adapter; private int threshold=2; private OnDismissListener listener; private boolean showing; public AutoCompleteTextView(android.content.Context c) { super(c); } public AutoCompleteTextView(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public AutoCompleteTextView(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public AutoCompleteTextView(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } public <T extends ListAdapter & Filterable> void setAdapter(T a) { adapter=a; } public ListAdapter getAdapter() { return adapter; } public void setThreshold(int n) { threshold=n; } public int getThreshold() { return threshold; } public boolean enoughToFilter() { return length()>=threshold; } public void showDropDown() { showing=true; } public void dismissDropDown() { if(showing && listener!=null) listener.onDismiss(); showing=false; } public boolean isPopupShowing() { return showing; } public void setOnDismissListener(OnDismissListener l) { listener=l; } public void onFilterComplete(int count) {} public void setCompletionHint(CharSequence hint) {} public void setDropDownBackgroundDrawable(android.graphics.drawable.Drawable d) { dropDownBackground=d; } public void setDropDownAnchor(int id) {} public void setDropDownHeight(int h) {} public void setDropDownWidth(int w) {}  private android.graphics.drawable.Drawable dropDownBackground; private AdapterView.OnItemClickListener itemClick; private AdapterView.OnItemSelectedListener itemSelected; public CharSequence convertSelectionToString(Object item) { return item==null?"":item.toString(); } public android.graphics.drawable.Drawable getDropDownBackground() { return dropDownBackground; } public AdapterView.OnItemClickListener getOnItemClickListener() { return itemClick; } public void setOnItemClickListener(AdapterView.OnItemClickListener l) { itemClick=l; } public AdapterView.OnItemSelectedListener getOnItemSelectedListener() { return itemSelected; } public void setOnItemSelectedListener(AdapterView.OnItemSelectedListener l) { itemSelected=l; } public void setText(CharSequence text,boolean filter) { setText(text); }
}
